# CoreWeave blog post on MLPerf Inference v6.1, held against the v6.0 and v6.1 result files. python3 -I check_claims_coreweave_v61.py
import json,hashlib,re
FILES=['raw/inf_6.0.json','raw/inf_6.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V0=json.loads(RAW[FILES[0]]); B=list(json.loads(RAW[FILES[1]]).values()); s=str; pc=lambda x,y:100*(x/y-1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
CLOUD={'Azure','CoreWeave','Crusoe','Google','Lambda','Nebius','Oracle'}
CW=[x for x in B if x['Organization']=='CoreWeave']
def cw(m,sysn,sc): r=[x for x in CW if x['Model']==m and sysn in x['SystemName'] and x['Scenario']==sc]; assert len(r)==1,(m,sysn,sc,len(r)); return r[0]['Result']
def acc(x):
    a=s(x['accelerator_model_name']); return 'GB300' if 'GB300' in a else 'GB200' if 'GB200' in a else 'B300' if 'B300' in a else 'B200' if 'B200' in a else a
def cl(m,sc,f=lambda x:True,av=True): return sorted([x for x in B if x['Division']=='closed' and (x['Availability']=='available' or not av) and x['Model']==m and x['Scenario']==sc and f(x)],key=lambda x:-x['Result'])
NV=lambda x:'NVIDIA' in s(x['accelerator_model_name'])
CV=[]
plat={acc(x) for x in CW}; mods={x['Model'] for x in CW}; av={(x['Division'],x['Availability']) for x in CW}
CV.append(mk('CV1','CoreWeave participated in the Datacenter Closed division’s Available category, submitting results across four NVIDIA platforms and four model families that are in use today.','CoreWeave entries in the v6.1 file','closed, available, four platforms, four model families',f'{sorted(av)}; platforms {sorted(plat)}; models {sorted(mods)}','CONSISTENT' if av=={('closed','available')} and len(plat)==4 and len(mods)==4 else 'BELOW',''))
qs=cl('qwen3-vl-235b-a22b','Server',lambda x:x['Organization'] in CLOUD)
qv=cw('qwen3-vl-235b-a22b','72x','Server'); qo=cw('qwen3-vl-235b-a22b','72x','Offline')
CV.append(mk('CV2','In server scenario, CoreWeave sustained 1,196 queries per second, the highest server throughput among cloud providers, and 1,135 samples per second in offline scenario.','CoreWeave 72 GPU GB300 Qwen3-VL entries against the other cloud provider entries','1,196 Server (highest among cloud providers), 1,135 Offline',f'Server {qv:,.2f} (top cloud provider entry {qs[0]["Organization"]} {qs[0]["Result"]:,.2f}, next {qs[1]["Organization"]} {qs[1]["Result"]:,.2f}), Offline {qo:,.2f}','CONSISTENT' if round(qv)==1196 and round(qo)==1135 and qs[0]['Organization']=='CoreWeave' else 'BELOW','Our cloud provider list: Azure, CoreWeave, Crusoe, Google, Lambda, Nebius, Oracle. The post names no list.'))
g1,g0=cw('deepseek-r1','GB200','Server')/72,[x for x in V0 if x['Submitter']=='CoreWeave' and x['Model']=='deepseek-r1' and x['Scenario']=='Server' and x['Total Accelerators']==64][0]['Performance_Result']/64
CV.append(mk('CV3','comparing the 72-GPU v6.1 submission with the 64-GPU v6.0 submission on NVIDIA GB200 NVL72,derived per-GPU Server throughput increased by 19.8%','CoreWeave GB200 NVL72 DeepSeek-R1 Server, v6.1 72 GPU entry over v6.0 64 GPU entry, each divided by its accelerator count','+19.8% per-GPU Server',f'{g1:,.1f} over {g0:,.1f}, {pc(g1,g0):+.2f}%','CONSISTENT' if round(pc(g1,g0),1)==19.8 else 'BELOW','Per-GPU is total divided by accelerators, a derived value the post marks as not verified by MLCommons.'))
po,ps=cw('gpt-oss-120b','GB300','Offline')/72,cw('gpt-oss-120b','GB300','Server')/72
CV.append(mk('CV4','CoreWeave sustained 16,635 tokens per second per GPU in offline scenario, and 16,118 in server scenario.','CoreWeave 72 GPU GB300 GPT-OSS-120B entries divided by 72','16,635 Offline and 16,118 Server per GPU',f'{po:,.1f} and {ps:,.1f}','CONSISTENT' if (round(po),round(ps))==(16635,16118) else 'BELOW',''))
def top_pg(sc,av): return sorted([(x['Result']/x['total_accelerators'],x['Organization'],x['total_accelerators'],x['Availability']) for x in cl('gpt-oss-120b',sc,av=av)],reverse=True)
tpo_all,tps_all=top_pg('Offline',False),top_pg('Server',False); tpo_av,tps_av=top_pg('Offline',True),top_pg('Server',True)
ok5=tpo_all[0][1]=='CoreWeave' and tps_all[0][1]=='CoreWeave'
CV.append(mk('CV5','These were the highest per-GPU throughput of any v6.1 Datacenter Closed submission on GPT-OSS-120B, on any silicon, in both scenarios.','closed v6.1 GPT-OSS-120B entries, result divided by accelerator count, all availability categories and available only','highest per-GPU in Offline and Server',f'all categories: Offline top {tpo_all[0][1]} {tpo_all[0][0]:,.0f} then {tpo_all[1][1]} {tpo_all[1][0]:,.0f}, Server top {tps_all[0][1]} {tps_all[0][0]:,.0f} then {tps_all[1][1]} {tps_all[1][0]:,.0f}; available only: Offline top {tpo_av[0][1]}, Server top {tps_av[0][1]}','CONSISTENT' if ok5 else ('BELOW' if tpo_av[0][1]=='CoreWeave' and tps_av[0][1]=='CoreWeave' else 'BELOW'),'Per-GPU is a derived value. The post marks it not verified by MLCommons.'+('' if ok5 else ' The preview category is counted in all categories.')))
CV.append(mk('CV6','CoreWeave achieved over 1.16 million tokens per second in server and over 1.19 million tokens per second in offline scenarios on a single NVIDIA GB300 NVL72 rack.','CoreWeave 72 GPU GB300 GPT-OSS-120B entries','over 1.16 million Server, over 1.19 million Offline',f'Server {cw("gpt-oss-120b","GB300","Server"):,.0f}, Offline {cw("gpt-oss-120b","GB300","Offline"):,.0f}','CONSISTENT' if cw('gpt-oss-120b','GB300','Server')>1.16e6 and cw('gpt-oss-120b','GB300','Offline')>1.19e6 else 'BELOW',''))
g2=cl('gpt-oss-120b','Server',lambda x:acc(x)=='GB200' and x['total_accelerators']==72); g2o=cl('gpt-oss-120b','Offline',lambda x:acc(x)=='GB200' and x['total_accelerators']==72)
CV.append(mk('CV7','Our NVIDIA GB200 NVL72 posted the highest rack-scale GPT-OSS-120B total in its class, reaching 901,058 tokens per second in server and 911,566 tokens per second in offline scenarios.','closed available v6.1 GPT-OSS-120B entries on 72 GB200 accelerators','highest total in class, 901,058 Server and 911,566 Offline',f'Server top {g2[0]["Organization"]} {g2[0]["Result"]:,.0f} of {len(g2)}, Offline top {g2o[0]["Organization"]} {g2o[0]["Result"]:,.0f} of {len(g2o)}','CONSISTENT' if g2[0]['Organization']=='CoreWeave' and g2o[0]['Organization']=='CoreWeave' and round(g2[0]['Result'])==901058 and round(g2o[0]['Result'])==911566 else 'BELOW','Our rule: class means 72 GB200 accelerators.'))
hg=lambda sc,a:[x for x in cl('gpt-oss-120b',sc,lambda y:y['Organization'] in CLOUD and y['total_accelerators']==8 and acc(y)==a)]
res=[(a,sc,hg(sc,a)[0]['Organization'],hg(sc,a)[0]['Result'],len(hg(sc,a))) for a in('B200','B300') for sc in('Server','Offline')]
CV.append(mk('CV8','Our NVIDIA HGX B200 and HGX B300 systems led all HGX submissions from cloud providers in both scenarios.','closed available v6.1 GPT-OSS-120B entries on eight B200 or eight B300 from cloud providers','led B200 and B300 in Server and Offline',', '.join(f'{a} {sc} top {o} {v:,.0f} of {n}' for a,sc,o,v,n in res),'CONSISTENT' if all(r[2]=='CoreWeave' for r in res) else 'BELOW','Our cloud provider list: Azure, CoreWeave, Crusoe, Google, Lambda, Nebius, Oracle. Cisco, Dell, HPE and other server makers are not counted.'))
lc=lambda sc:cl('llama2-70b-99.9',sc,lambda y:y['Organization'] in CLOUD and acc(y)=='GB300' and y['total_accelerators']==72)
ls,lo=lc('Server'),lc('Offline')
CV.append(mk('CV9','We delivered the highest throughput among cloud providers with NVIDIA GB300 NVL72 with a throughput of 944,902 tokens per second in server scenario and 1,136,100 in offline scenario.','closed available v6.1 Llama 2 70B entries from cloud providers on 72 GB300','highest, 944,902 Server and 1,136,100 Offline',f'Server top {ls[0]["Organization"]} {ls[0]["Result"]:,.0f} of {len(ls)} (CoreWeave {cw("llama2-70b-99.9","GB300","Server"):,.0f}); Offline top {lo[0]["Organization"]} {lo[0]["Result"]:,.0f} of {len(lo)}','CONSISTENT' if ls[0]['Organization']=='CoreWeave' and lo[0]['Organization']=='CoreWeave' and round(ls[0]['Result'])==944902 and round(lo[0]['Result'])==1136100 else 'BELOW','Llama 2 70B is read as llama2-70b-99.9, the only Llama 2 70B variant CoreWeave submitted. CoreWeave is the only cloud provider entry on 72 GB300 for this model in the file, so the ranking is by the absence of other entries.'))
mil=[x for x in lo if x['Result']>1e6]
CV.append(mk('CV10','In the offline scenario, we achieved the only result above one million tokens per second among cloud provider submissions using NVIDIA GB300 NVL72.','closed available v6.1 Llama 2 70B Offline entries from cloud providers on 72 GB300','only one above 1,000,000',f'{len(mil)} above one million: {[x["Organization"] for x in mil]}','CONSISTENT' if len(mil)==1 and mil[0]['Organization']=='CoreWeave' else 'BELOW','CoreWeave is the only cloud provider entry in this group in the file.'))
agg_o=sorted([(x['Result'],x['Organization'],x['total_accelerators']) for x in cl('gpt-oss-120b','Offline',NV)],reverse=True)[:3]
agg72=sorted([(x['Result'],x['Organization'],acc(x)) for x in cl('gpt-oss-120b','Offline',lambda y:NV(y) and y['total_accelerators']==72)],reverse=True)[:3]
CV.append(mk('CV11','highest aggregate throughput of any NVIDIA-based system, on a single GB300 NVL72 rack','closed available v6.1 GPT-OSS-120B Offline entries on NVIDIA accelerators','highest aggregate of any NVIDIA-based system, single GB300 rack',f'all NVIDIA entries top three {[(o,n,round(v)) for v,o,n in agg_o]}; 72 GPU entries top three {[(o,a,round(v)) for v,o,a in agg72]}','CONSISTENT' if agg_o[0][1]=='CoreWeave' else ('CONSISTENT' if agg72[0][1]=='CoreWeave' and agg72[0][2]=='GB300' else 'BELOW'),'Read as the single-rack claim if a larger NVIDIA system exists. The first reading counts every NVIDIA entry in the file, the second only 72 GPU entries.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=CV),open('claims_coreweave_v61.json','w'),indent=1)
for c in CV: print(c['id'],c['outcome'],'|',c['stated'][:48],'|',c['delivered'][:260])
